using UnityEngine; namespace Reflectable { [RequireComponent(typeof(Rigidbody2D),typeof(Collider2D))] public sealed class ReflectableProjectile:MonoBehaviour { Rigidbody2D body; ReflectableGameController game; int damage; float speed,startedAt; bool launched,exiting; void Awake(){body=GetComponent<Rigidbody2D>();body.gravityScale=0f;body.collisionDetectionMode=CollisionDetectionMode2D.Continuous;body.freezeRotation=true;} public void Launch(ReflectableGameController owner,Vector2 direction,float launchSpeed,int initialDamage){game=owner;damage=initialDamage;speed=launchSpeed;startedAt=Time.time;launched=true;body.linearVelocity=direction.normalized*speed;} public void AddDamage(int amount){damage+=amount;} void OnCollisionEnter2D(Collision2D hit){if(!launched)return;var normal=hit.contactCount>0?hit.GetContact(0).normal:Vector2.up;body.linearVelocity=Vector2.Reflect(body.linearVelocity.normalized,normal).normalized*speed;var block=hit.collider.GetComponent<ReflectableBlockView>();if(block)game.HitBlock(block,damage);else game.RegisterRicochet(this);} void OnTriggerEnter2D(Collider2D other){if(other.isTrigger&&(other.name=="BottomBoundary"||other.CompareTag("ProjectileKill")))Exit();} void Update(){if(launched&&(transform.position.y<-5.2f||Time.time-startedAt>20f))Exit();} void Exit(){if(exiting)return;exiting=true;if(game)game.ProjectileExited();Destroy(gameObject);} } }
